task pair_OR_Sum(arr: seq, n: int) returns (r: int)
  requires n >= 0
  requires n <= len(arr)
  ensures r == 0
  ensures n == 0
{
  r := 0;
  var i: int := 0;
  while i < n
    invariant 0 <= i and i <= n
    invariant r == 0
    decreases n - i
  {
    var j: int := i + 1;
    while j < n
      invariant i < j and j <= n
      invariant r == 0
      decreases n - j
    {
      r := r + arr[i] + arr[j];
      j := j + 1;
    }
    i := i + 1;
  }
}
